export function WhatsNewPanel({
  title = "{{title}}",
  entriesShown = {{entriesShown}},
  newFlag = {{newFlag}},
  accent = "{{accent}}",
  style = "{{style}}",
  dismissLabel = "{{dismissLabel}}",
}) {
  const entries = [
    { title: "Faster search across your workspace", date: "12 Aug" },
    { title: "Dark mode for the mobile app", date: "5 Aug" },
    { title: "Bulk export for reports", date: "29 Jul" },
  ].slice(0, entriesShown);
  const compact = style === "compact";
  const timeline = style === "timeline";
  return (
    <div style={{ position: "relative", font: "16px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: "18px 20px", maxWidth: 320, borderRadius: 14, border: "1px solid #24143018" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <h3 style={{ margin: 0, fontSize: 15, fontWeight: 700 }}>{title}</h3>
        <button type="button" aria-label={dismissLabel} style={{ width: 22, height: 22, border: "none", background: "transparent", color: "#24143070", fontSize: 14, borderRadius: 6, cursor: "pointer" }}>×</button>
      </div>
      <ul style={{ listStyle: "none", margin: 0, padding: timeline ? "0 0 0 14px" : 0, borderLeft: timeline ? "1.5px solid #24143018" : "none", display: "flex", flexDirection: "column", gap: 12 }}>
        {entries.map((e, i) => (
          <li key={e.title} style={{ position: "relative", display: compact ? "flex" : "block", alignItems: compact ? "baseline" : "normal", gap: compact ? 8 : 0 }}>
            {timeline && <span style={{ position: "absolute", left: -18.5, top: 4, width: 8, height: 8, borderRadius: 999, background: accent }} />}
            {i === 0 && newFlag && (
              <span style={{ display: "inline-block", fontSize: 9.5, fontWeight: 800, textTransform: "uppercase", letterSpacing: ".03em", padding: "2px 6px", borderRadius: 999, background: accent, marginBottom: 4 }}>New</span>
            )}
            <p style={{ margin: "0 0 2px", fontSize: 13, fontWeight: 600 }}>{e.title}</p>
            <p style={{ margin: 0, fontSize: 11, color: "#24143090" }}>{e.date}</p>
          </li>
        ))}
      </ul>
    </div>
  );
}
